{"name": "write_file", "arguments": {"file_path": "/path/to/project/app/reconcile.py", "content": "#!/usr/bin/env python3

import argparse
import json
from datetime import datetime, timezone
from decimal import Decimal, getcontext

getcontext().prec = 2

def parse_timestamp(ts_str):
    return datetime.fromisoformat(ts_str).astimezone(timezone.utc)

def process_csv(file_path):
    transactions = {}
    with open(file_path, 'r') as file:
        for line in file:
            try:
                parts = line.strip().split(',
')
                tx_id, timestamp, amount, status = parts
                amount = Decimal(amount)
                timestamp = parse_timestamp(timestamp)
            except (ValueError, TypeError, IndexError):
                continue

            if tx_id not in transactions or timestamp > transactions[tx_id]['timestamp']:
                transactions[tx_id] = {'timestamp': timestamp, 'amount': amount, 'status': status}

    total_valid_amount = Decimal(0)
    valid_count = 0
    failed_count = 0

    for _, data in transactions.items():
        if data['status'] == 'SUCCESS':
            total_valid_amount += data['amount']
            valid_count += 1
        elif data['status'] == 'FAILED':
            failed_count += 1

    return {
        'total_valid_amount': float(total_valid_amount),
        'valid_count': valid_count,
        'failed_count': failed_count
    }

def main():
    parser = argparse.ArgumentParser(description='Process a CSV file for payment reconciliation.')
    parser.add_argument('file_path', type=str, help='Path to the input CSV file.')
    args = parser.parse_args()

    try:
        result = process_csv(args.file_path)
        print(json.dumps(result))
    except FileNotFoundError as e:
        import sys
        print(f'Error: {e}', file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
